	"BridgeManagementV2/restrictions/i18n/i18n.properties":'appTitle = Restrictions Registry\n\n# Override FE4 default "Object saved" toast \\u2014 {0} is replaced with @UI.HeaderInfo.TypeName\nC_TRANSACTION_HELPER_DRAFT_OBJECT_SAVED={0} saved successfully\nappSubTitle = Network-level & policy restrictions\nappDescription = Manage network-wide and policy-level restrictions. Bridge-specific restrictions (load limits, height, width) are managed from the individual Bridge record.\n\n# Validation: required fields\nerror.bridge.required=Bridge is required: enter or select a Bridge ID\nerror.restrictionCategory.required=Category is required\nerror.restrictionType.required=Restriction Type is required\nerror.restrictionValue.required=Value is required\nerror.restrictionUnit.required=Unit is required\nerror.effectiveFrom.required=Effective From date is required\nerror.temporaryFrom.required=Temporary From date is required when category is Temporary\nerror.temporaryTo.required=Temporary To date is required when category is Temporary\n\n# Validation: date logic\nerror.effectiveTo.beforeFrom=Effective To must be on or after Effective From\nerror.temporaryTo.beforeFrom=Temporary To must be on or after Temporary From\n\n# Validation: physical limit ranges\nerror.speedLimit.range=Speed Limit must be between 0 and 130 km/h\nerror.grossMassLimit.range=Gross Mass Limit must be between 0 and 1,000 t\nerror.axleMassLimit.range=Axle Mass Limit must be between 0 and 500 t\nerror.heightLimit.range=Height Limit must be between 0 and 30 m\nerror.widthLimit.range=Width Limit must be between 0 and 100 m\nerror.lengthLimit.range=Length Limit must be between 0 and 1,000 m\n\n# Warnings\nwarning.gazetteExpiringSoon=Gazette authority expires in {0} days. Renewal required.\nwarning.gazetteExpired=Gazette authority has EXPIRED. This restriction may not have legal authority.\nwarning.effectiveToInPast=Effective To date is in the past: this restriction may already be expired.\n',
